#include <stdio.h>

typedef enum { R0, R1, R2, R3 } Reg;

void mov(int *regs, Reg dst, Reg src) { regs[dst] = regs[src]; }
void add(int *regs, Reg dst, Reg src) { regs[dst] += regs[src]; }
void sub(int *regs, Reg dst, Reg src) { regs[dst] -= regs[src]; }

void print(int *regs) {
    printf("r0:%d r1:%d r2:%d r3:%d\n", regs[0], regs[1], regs[2], regs[3]);
}

int main() {
    int regs[4] = {0};
    regs[R0] = 10; regs[R1] = 5;
    mov(regs, R2, R0);
    add(regs, R2, R1);
    sub(regs, R0, R1);
    print(regs);
    return 0;
}
